public static int findNthLeapYear(int Y, int N) {
    // Step 1: Validate inputs
    if (Y <= 0 || N <= 0) {
        throw new IllegalArgumentException("Y and N must be positive integers");
    }

    // Step 2: Calculate the Nth leap year after Y
    int currentYear = Y;
    for (int i = 0; i < N; i++) {
        // Check if the current year is a leap year
        if (currentYear % 4 == 0 && (currentYear % 100 != 0 || currentYear % 400 == 0)) {
            N--;
        }
        currentYear++;
    }

    // Step 3: Return the Nth leap year after Y
    return currentYear;
}

