public List<List<Integer>> permute(int[] nums) {
    List<List<Integer>> result = new ArrayList<>();
    if (nums == null || nums.length == 0) {
        return result;
    }

    // Initialize the result list with the first permutation
    result.add(Arrays.asList(nums));

    // Add the remaining permutations
    for (int i = 1; i < nums.length; i++) {
        int num = nums[i];
        int j = 0;
        while (j < result.size()) {
            List<Integer> curPerm = result.get(j);
            List<Integer> newPerm = new ArrayList<>(curPerm);
            newPerm.add(num);
            result.add(newPerm);
            j++;
        }
    }

    return result;
}

