public static String appx(String word1, String word2) {
  StringBuilder result = new StringBuilder();

  int commonLetters = 0;
  for (char c : word1.toCharArray()) {
    if (word2.contains(String.valueOf(c))) {
      commonLetters++;
    }
  }

  int denominator = word1.length() + word2.length();
  result.append("appx(").append(word1).append(", ").append(word2).append(") = ");
  if (commonLetters == 0) {
    result.append("0");
  } else {
    result.append(commonLetters).append("/").append(denominator);
  }

  return result.toString();
}

