public String sortString(String s) {
    if (s == null || s.isEmpty()) {
        return s;
    }

    String sortedString = "";
    List<Character> chars = new ArrayList<>(s.length());

    for (char c : s.toCharArray()) {
        chars.add(c);
    }

    while (!chars.isEmpty()) {
        Character min = chars.get(0);
        chars.remove(0);
        sortedString += min;

        for (int i = 0; i < chars.size(); i++) {
            Character next = chars.get(i);
            if (next > min) {
                sortedString += next;
                chars.remove(i);
                break;
            }
        }
    }

    return sortedString;
}

