    if (k <= 0) {
        return false;
    }

    // Edge case: s has fewer than k binary digits.
    if (s.length() < k) {
        return false;
    }

    // Initialize a set to store all binary strings of length k.
    Set<String> binaryStrings = new HashSet<>();

    // Iterate over the binary digits of s in blocks of length k.
    for (int i = 0; i <= s.length() - k; i++) {
        // Get the current block of length k.
        String currentBlock = s.substring(i, i + k);

        // If the current block is a substring of s, add it to the set of binary strings.
        if (s.contains(currentBlock)) {
            binaryStrings.add(currentBlock);
        }
    }

    // Return true if the set of binary strings contains all possible binary strings of length k.
    return binaryStrings.size() == (int) Math.pow(2, k);
}

