public int minInsertions(String s) {
    // Step 1: Count the number of left and right brackets in the input string
    int leftCount = 0;
    int rightCount = 0;
    for (char c : s.toCharArray()) {
        if (c == '(') {
            leftCount++;
        } else if (c == ')') {
            rightCount++;
        }
    }

    // Step 2: Calculate the difference between the left and right brackets
    int diff = leftCount - rightCount;

    // Step 3: Insert the necessary brackets to make the string balanced
    int insertions = 0;
    if (diff > 0) {
        // If there are more left brackets than right brackets,
        // add right brackets to the end of the string
        insertions += diff;
    } else if (diff < 0) {
        // If there are more right brackets than left brackets,
        // add left brackets to the beginning of the string
        insertions -= diff;
    }

    return insertions;
}

