public int minOperations(int n) {
  int[] arr = new int[n];
  for (int i = 0; i < n; i++) {
    arr[i] = (2 * i) + 1;
  }

  // Initialize minOps to the maximum possible value
  int minOps = Integer.MAX_VALUE;

  // Loop through each possible operation
  for (int x = 0; x < n; x++) {
    for (int y = 0; y < n; y++) {
      if (x == y) continue;

      // Perform the operation
      arr[x] -= 1;
      arr[y] += 1;

      // Check if all elements are equal
      boolean allEqual = true;
      for (int i = 0; i < n - 1; i++) {
        if (arr[i] != arr[i + 1]) {
          allEqual = false;
          break;
        }
      }

      // If all elements are equal, update minOps
      if (allEqual) {
        minOps = Math.min(minOps, x - y);
      }

      // Undo the operation
      arr[x] += 1;
      arr[y] -= 1;
    }
  }

  return minOps;
}

