public int minOperations(int n) {
  if (n < 2) {
    return 0;
  }
  int minOperations = Integer.MAX_VALUE;
  int[] arr = new int[n];
  for (int i = 0; i < n; i++) {
    arr[i] = (2 * i) + 1;
  }
  for (int i = 0; i < n - 1; i++) {
    for (int j = i + 1; j < n; j++) {
      int temp = arr[i] + arr[j];
      if (temp % 2 == 0) {
        int numOperations = 0;
        for (int k = 0; k < n; k++) {
          if (arr[k] % 2 == 0) {
            continue;
          }
          if (k == i || k == j) {
            continue;
          }
          int x = k;
          int y = (k + n - 1) % n;
          arr[x] -= 1;
          arr[y] += 1;
          numOperations++;
        }
        minOperations = Math.min(minOperations, numOperations);
      }
    }
  }
  return minOperations;
}

